import{_ as o,o as t,c as s,ag as n}from"./chunks/framework.CvgP6Fyv.js";const m=JSON.parse('{"title":"PostMan工具的使用","description":"","frontmatter":{},"headers":[],"relativePath":"docs/java/Spring全家桶/SpringMVC/PostMan工具的使用.md","filePath":"docs/java/Spring全家桶/SpringMVC/PostMan工具的使用.md"}'),e={name:"docs/java/Spring全家桶/SpringMVC/PostMan工具的使用.md"};function r(p,a,i,l,d,h){return t(),s("div",null,[...a[0]||(a[0]=[n('<h1 id="postman工具的使用" tabindex="-1">PostMan工具的使用 <a class="header-anchor" href="#postman工具的使用" aria-label="Permalink to &quot;PostMan工具的使用&quot;">​</a></h1><h2 id="postman简介" tabindex="-1">PostMan简介 <a class="header-anchor" href="#postman简介" aria-label="Permalink to &quot;PostMan简介&quot;">​</a></h2><p>代码编写完后，我们要想测试，只需要打开浏览器直接输入地址发送请求即可。但是我们如果我们发送的是<code>GET</code>请求可以直接使用浏览器，但是如果要发送的是<code>POST</code>请求呢?</p><p>如果要求发送的是post请求，我们就得准备页面在页面上准备form表单，测试起来比较麻烦。所以我们就需要借助一些第三方工具，如PostMan.</p><ul><li><p>PostMan是一款功能强大的网页调试与发送网页HTTP请求的Chrome插件。<img src="https://lsky-pro.qinlaoshi.dpdns.org:2083/qls/1630463382386.png" alt="1630463382386"></p></li><li><p>作用：常用于进行接口测试</p></li><li><p>特征</p><ul><li>简单</li><li>实用</li><li>美观</li><li>大方</li></ul></li></ul><h2 id="postman安装" tabindex="-1">PostMan安装 <a class="header-anchor" href="#postman安装" aria-label="Permalink to &quot;PostMan安装&quot;">​</a></h2><p>双击<code>资料\\Postman-win64-8.3.1-Setup.exe</code>即可自动安装，</p><p>安装完成后，如果需要注册，可以按照提示进行注册，如果底部有跳过测试的链接也可以点击跳过注册</p><p><img src="https://lsky-pro.qinlaoshi.dpdns.org:2083/qls/1630463816424.png" alt="1630463816424"></p><p>看到如下界面，就说明已经安装成功。</p><p><img src="https://lsky-pro.qinlaoshi.dpdns.org:2083/qls/1630463887711.png" alt="1630463887711"></p><h2 id="postman使用" tabindex="-1">PostMan使用 <a class="header-anchor" href="#postman使用" aria-label="Permalink to &quot;PostMan使用&quot;">​</a></h2><h3 id="创建workspace工作空间" tabindex="-1">创建WorkSpace工作空间 <a class="header-anchor" href="#创建workspace工作空间" aria-label="Permalink to &quot;创建WorkSpace工作空间&quot;">​</a></h3><p><img src="https://lsky-pro.qinlaoshi.dpdns.org:2083/qls/image-20210805150044862.png" alt="20210805150044862"></p><h3 id="发送请求" tabindex="-1">发送请求 <a class="header-anchor" href="#发送请求" aria-label="Permalink to &quot;发送请求&quot;">​</a></h3><p><img src="https://lsky-pro.qinlaoshi.dpdns.org:2083/qls/1630464489898.png" alt="1630464489898"></p><h3 id="保存当前请求" tabindex="-1">保存当前请求 <a class="header-anchor" href="#保存当前请求" aria-label="Permalink to &quot;保存当前请求&quot;">​</a></h3><p><img src="https://lsky-pro.qinlaoshi.dpdns.org:2083/qls/1630464783034.png" alt="1630464783034"></p><p>**注意:**第一次请求需要创建一个新的目录，后面就不需要创建新目录，直接保存到已经创建好的目录即可。</p>',19)])])}const P=o(e,[["render",r]]);export{m as __pageData,P as default};
